<?php
require_once __DIR__.'/../includes/config.php';require_once __DIR__.'/../includes/session.php';if(session_status()===PHP_SESSION_NONE)session_start();if(empty($_SESSION['rider_id'])){header('Location:rider-login.php');exit;}$rid=(int)$_SESSION['rider_id'];function eh($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$completed=0;$total=0;$today=0;$month=0;$history=[];
$sql="SELECT rd.order_id,rd.delivered_at,o.order_number,o.total,o.delivery_fee,o.created_at,r.name restaurant_name FROM rider_deliveries rd JOIN orders o ON o.id=rd.order_id LEFT JOIN restaurants r ON r.id=o.restaurant_id WHERE rd.rider_id=? AND rd.status='delivered' ORDER BY rd.delivered_at DESC";$st=$conn->prepare($sql);if($st){$st->bind_param('i',$rid);$st->execute();$rs=$st->get_result();while($x=$rs->fetch_assoc()){$history[]=$x;$completed++;$earning=(float)$x['delivery_fee'];$total+=$earning;if(!empty($x['delivered_at'])){if(date('Y-m-d',strtotime($x['delivered_at']))===date('Y-m-d'))$today+=$earning;if(date('Y-m',strtotime($x['delivered_at']))===date('Y-m'))$month+=$earning;}}$st->close();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Earnings | Humsafar</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><style>*{box-sizing:border-box}body{margin:0;background:#f7f7f9;font:14px Segoe UI,Arial;color:#222}.page{margin-left:223px;padding:32px;max-width:1200px}h1{margin:0;font-size:32px}.sub{color:#777}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin:25px 0}.stat{background:#fff;border:1px solid #eee;border-radius:15px;padding:20px}.stat i{color:#ed0038;float:right}.stat small{color:#888}.stat b{display:block;font-size:25px;margin-top:7px}.card{background:#fff;border:1px solid #eee;border-radius:16px;padding:20px}.table{width:100%;border-collapse:collapse}.table th,.table td{text-align:left;padding:13px;border-bottom:1px solid #eee}.table th{font-size:12px;color:#888}@media(max-width:900px){.page{margin-left:0;padding:20px}.stats{grid-template-columns:1fr 1fr}.table{display:block;overflow:auto;white-space:nowrap}}</style></head><body><?php include __DIR__.'/rider-sidebar.php';?><main class="page"><h1>Earnings</h1><p class="sub">Your delivery earnings and completed delivery history.</p><div class="stats"><div class="stat"><i class="fa-solid fa-calendar-day"></i><small>Today</small><b>Rs <?=number_format($today,0)?></b></div><div class="stat"><i class="fa-solid fa-calendar"></i><small>This Month</small><b>Rs <?=number_format($month,0)?></b></div><div class="stat"><i class="fa-solid fa-wallet"></i><small>Total Earnings</small><b>Rs <?=number_format($total,0)?></b></div><div class="stat"><i class="fa-solid fa-check-double"></i><small>Completed</small><b><?=$completed?></b></div></div><div class="card"><h2>Delivery Earnings</h2><?php if(!$history):?><p style="color:#888;text-align:center;padding:35px">No completed deliveries yet.</p><?php else:?><table class="table"><tr><th>Order</th><th>Restaurant</th><th>Delivered</th><th>Delivery Fee</th></tr><?php foreach($history as $x):?><tr><td>#<?=eh($x['order_number']?:$x['order_id'])?></td><td><?=eh($x['restaurant_name']?:'Restaurant')?></td><td><?=eh($x['delivered_at']?date('d M Y, h:i A',strtotime($x['delivered_at'])):'—')?></td><td><b>Rs <?=number_format((float)$x['delivery_fee'],0)?></b></td></tr><?php endforeach;?></table><?php endif;?></div></main></body></html>